// Lesson: Parallel Tool Calls and Streaming with Tools (phase 13 / lesson 03)
// Go port of code/main.py. Go standard library only.
// Source: phases/13-tools-and-protocols/03-parallel-and-streaming-tool-calls/docs/en.md
// Run: go run code/main.go

package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"sync"
	"time"
)

var cityOrder = []string{"Bengaluru", "Tokyo", "Zurich"}

var simulatedLatencyMS = map[string]int{"Bengaluru": 400, "Tokyo": 600, "Zurich": 800}

type weather struct {
	City  string
	TempC uint32
}

func (w weather) String() string {
	return fmt.Sprintf("{'city': '%s', 'temp_c': %d}", w.City, w.TempC)
}

func stableHash(s string) uint32 {
	var h uint32
	for _, c := range s {
		h = h*31 + uint32(c)
	}
	return h
}

func executorWeather(city string) weather {
	latency, ok := simulatedLatencyMS[city]
	if !ok {
		latency = 500
	}
	time.Sleep(time.Duration(latency) * time.Millisecond)
	return weather{City: city, TempC: stableHash(city) % 35}
}

func runSequential(cities []string) (float64, []weather) {
	start := time.Now()
	results := make([]weather, 0, len(cities))
	for _, c := range cities {
		results = append(results, executorWeather(c))
	}
	return float64(time.Since(start).Microseconds()) / 1000, results
}

func runParallel(cities []string) (float64, []weather) {
	start := time.Now()
	results := make([]weather, len(cities))
	var wg sync.WaitGroup
	for i, c := range cities {
		wg.Add(1)
		go func(i int, c string) {
			defer wg.Done()
			results[i] = executorWeather(c)
		}(i, c)
	}
	wg.Wait()
	return float64(time.Since(start).Microseconds()) / 1000, results
}

type callBuffer struct {
	id      string
	name    string
	argsBuf string
	done    bool
}

func (b *callBuffer) tryParse() map[string]string {
	if !b.done {
		return nil
	}
	var out map[string]string
	if err := json.Unmarshal([]byte(b.argsBuf), &out); err != nil {
		panic(err)
	}
	return out
}

type streamAccumulator struct {
	buffers map[string]*callBuffer
}

type event struct {
	kind  string
	id    string
	name  string
	chunk string
}

func (a *streamAccumulator) onEvent(e event) []*callBuffer {
	var completed []*callBuffer
	switch e.kind {
	case "call_start":
		a.buffers[e.id] = &callBuffer{id: e.id, name: e.name}
	case "args_delta":
		a.buffers[e.id].argsBuf += e.chunk
	case "call_stop":
		buf := a.buffers[e.id]
		buf.done = true
		completed = append(completed, buf)
	}
	return completed
}

func fakeOpenAIStream() []event {
	return []event{
		{kind: "call_start", id: "call_A", name: "get_weather"},
		{kind: "call_start", id: "call_B", name: "get_weather"},
		{kind: "call_start", id: "call_C", name: "get_weather"},
		{kind: "args_delta", id: "call_A", chunk: `{"city"`},
		{kind: "args_delta", id: "call_B", chunk: `{"city`},
		{kind: "args_delta", id: "call_A", chunk: `:"Beng`},
		{kind: "args_delta", id: "call_C", chunk: `{"city":"Zu`},
		{kind: "args_delta", id: "call_A", chunk: `aluru"}`},
		{kind: "call_stop", id: "call_A"},
		{kind: "args_delta", id: "call_B", chunk: `":"Tokyo"}`},
		{kind: "call_stop", id: "call_B"},
		{kind: "args_delta", id: "call_C", chunk: `rich"}`},
		{kind: "call_stop", id: "call_C"},
	}
}

type flight struct {
	id     string
	result chan weather
}

func replayAndExecute() []flight {
	acc := &streamAccumulator{buffers: map[string]*callBuffer{}}
	var inFlight []flight
	for _, e := range fakeOpenAIStream() {
		for _, buf := range acc.onEvent(e) {
			args := buf.tryParse()
			fmt.Printf("  call %s args complete -> {'city': '%s'}\n", buf.id, args["city"])
			ch := make(chan weather, 1)
			go func(city string) { ch <- executorWeather(city) }(args["city"])
			inFlight = append(inFlight, flight{id: buf.id, result: ch})
		}
	}
	return inFlight
}

func main() {
	bar := strings.Repeat("=", 72)
	fmt.Println(bar)
	fmt.Println("PHASE 13 LESSON 03 - PARALLEL AND STREAMING TOOL CALLS")
	fmt.Println(bar)

	sumLat, maxLat := 0, 0
	parts := make([]string, 0, len(cityOrder))
	for _, c := range cityOrder {
		v := simulatedLatencyMS[c]
		sumLat += v
		if v > maxLat {
			maxLat = v
		}
		parts = append(parts, fmt.Sprintf("'%s': %d", c, v))
	}

	fmt.Println("\n--- demo 1: three-city weather (simulated) ---")
	fmt.Printf("per-city simulated latency : {%s}\n", strings.Join(parts, ", "))
	fmt.Printf("theoretical sequential     : %d ms  (sum)\n", sumLat)
	fmt.Printf("theoretical parallel       : %d ms  (max)\n", maxLat)

	seqMS, _ := runSequential(cityOrder)
	parMS, _ := runParallel(cityOrder)
	fmt.Printf("\nactual sequential : %.0f ms\n", seqMS)
	fmt.Printf("actual parallel   : %.0f ms\n", parMS)
	speedup := 0.0
	if parMS > 0 {
		speedup = seqMS / parMS
	}
	fmt.Printf("speedup           : %.2fx\n", speedup)

	fmt.Println("\n--- demo 2: stream accumulator ---")
	fmt.Println("replaying fake interleaved stream of three parallel calls ...")
	inFlight := replayAndExecute()
	fmt.Println("\nfinal results (keyed by tool_call_id):")
	for _, f := range inFlight {
		fmt.Printf("  %s -> %s\n", f.id, <-f.result)
	}
}

"""Phase 13 Lesson 03 - parallel and streaming tool calls.

Two demos, stdlib only:
  1. Three-city weather run, sequential vs parallel (thread pool).
     Measures wall-clock and shows the max vs sum pattern.
  2. Stream accumulator for out-of-order argument chunks.
     Replays a fake OpenAI-shaped stream of three interleaved parallel calls
     and reassembles each per-id before executing.

Run: python code/main.py
"""

from __future__ import annotations

import json
import time
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field


# ------------------------------------------------------------------
# demo 1: sequential vs parallel weather lookup
# ------------------------------------------------------------------

SIMULATED_LATENCY_MS = {"Bengaluru": 400, "Tokyo": 600, "Zurich": 800}


def executor_weather(city: str) -> dict:
    latency = SIMULATED_LATENCY_MS.get(city, 500)
    time.sleep(latency / 1000.0)
    return {"city": city, "temp_c": hash(city) % 35}


def run_sequential(cities: list[str]) -> tuple[float, list[dict]]:
    start = time.perf_counter()
    results = [executor_weather(c) for c in cities]
    dt_ms = (time.perf_counter() - start) * 1000
    return dt_ms, results


def run_parallel(cities: list[str]) -> tuple[float, list[dict]]:
    start = time.perf_counter()
    with ThreadPoolExecutor(max_workers=len(cities)) as pool:
        results = list(pool.map(executor_weather, cities))
    dt_ms = (time.perf_counter() - start) * 1000
    return dt_ms, results


# ------------------------------------------------------------------
# demo 2: stream accumulator
# ------------------------------------------------------------------

@dataclass
class CallBuffer:
    id: str
    name: str = ""
    args_buf: str = ""
    done: bool = False

    def try_parse(self) -> dict | None:
        if not self.done:
            return None
        return json.loads(self.args_buf)


@dataclass
class StreamAccumulator:
    buffers: dict[str, CallBuffer] = field(default_factory=dict)

    def on_event(self, event: dict) -> list[CallBuffer]:
        kind = event["type"]
        idx = event.get("id")
        completed: list[CallBuffer] = []
        if kind == "call_start":
            self.buffers[idx] = CallBuffer(id=idx, name=event["name"])
        elif kind == "args_delta":
            buf = self.buffers[idx]
            buf.args_buf += event["chunk"]
        elif kind == "call_stop":
            buf = self.buffers[idx]
            buf.done = True
            completed.append(buf)
        return completed


def fake_openai_stream():
    """Three interleaved parallel calls. Real streams look like this."""
    yield {"type": "call_start", "id": "call_A", "name": "get_weather"}
    yield {"type": "call_start", "id": "call_B", "name": "get_weather"}
    yield {"type": "call_start", "id": "call_C", "name": "get_weather"}
    yield {"type": "args_delta", "id": "call_A", "chunk": '{"city"'}
    yield {"type": "args_delta", "id": "call_B", "chunk": '{"city'}
    yield {"type": "args_delta", "id": "call_A", "chunk": ':"Beng'}
    yield {"type": "args_delta", "id": "call_C", "chunk": '{"city":"Zu'}
    yield {"type": "args_delta", "id": "call_A", "chunk": 'aluru"}'}
    yield {"type": "call_stop", "id": "call_A"}
    yield {"type": "args_delta", "id": "call_B", "chunk": '":"Tokyo"}'}
    yield {"type": "call_stop", "id": "call_B"}
    yield {"type": "args_delta", "id": "call_C", "chunk": 'rich"}'}
    yield {"type": "call_stop", "id": "call_C"}


def replay_and_execute() -> dict[str, dict]:
    acc = StreamAccumulator()
    results: dict[str, dict] = {}
    in_flight: dict[str, "Future"] = {}  # type: ignore
    with ThreadPoolExecutor(max_workers=4) as pool:
        for event in fake_openai_stream():
            completed = acc.on_event(event)
            for buf in completed:
                args = buf.try_parse()
                print(f"  call {buf.id} args complete -> {args}")
                in_flight[buf.id] = pool.submit(executor_weather, args["city"])
        for cid, fut in in_flight.items():
            results[cid] = fut.result()
    return results


# ------------------------------------------------------------------
# main
# ------------------------------------------------------------------

def main() -> None:
    print("=" * 72)
    print("PHASE 13 LESSON 03 - PARALLEL AND STREAMING TOOL CALLS")
    print("=" * 72)

    cities = ["Bengaluru", "Tokyo", "Zurich"]
    sum_lat = sum(SIMULATED_LATENCY_MS.values())
    max_lat = max(SIMULATED_LATENCY_MS.values())

    print("\n--- demo 1: three-city weather (simulated) ---")
    print(f"per-city simulated latency : {SIMULATED_LATENCY_MS}")
    print(f"theoretical sequential     : {sum_lat} ms  (sum)")
    print(f"theoretical parallel       : {max_lat} ms  (max)")

    seq_ms, seq_res = run_sequential(cities)
    par_ms, par_res = run_parallel(cities)
    print(f"\nactual sequential : {seq_ms:.0f} ms")
    print(f"actual parallel   : {par_ms:.0f} ms")
    speedup = seq_ms / par_ms if par_ms else 0
    print(f"speedup           : {speedup:.2f}x")

    print("\n--- demo 2: stream accumulator ---")
    print("replaying fake interleaved stream of three parallel calls ...")
    results = replay_and_execute()
    print("\nfinal results (keyed by tool_call_id):")
    for cid, r in results.items():
        print(f"  {cid} -> {r}")


if __name__ == "__main__":
    main()

// Lesson: Parallel Tool Calls and Streaming with Tools (phase 13 / lesson 03)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/13-tools-and-protocols/03-parallel-and-streaming-tool-calls/docs/en.md
// Run: npx tsx phases/13-tools-and-protocols/03-parallel-and-streaming-tool-calls/code/main.ts

import { performance } from "node:perf_hooks";
import { setTimeout as sleep } from "node:timers/promises";

type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
type JsonObject = { [key: string]: Json };

function pyStrRepr(s: string): string {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = "";
  for (const c of s) {
    if (c === "\\") out += "\\\\";
    else if (c === quote) out += "\\" + c;
    else if (c === "\n") out += "\\n";
    else if (c === "\r") out += "\\r";
    else if (c === "\t") out += "\\t";
    else out += c;
  }
  return quote + out + quote;
}

function pyRepr(value: Json): string {
  if (value === null) return "None";
  if (typeof value === "boolean") return value ? "True" : "False";
  if (typeof value === "number") return String(value);
  if (typeof value === "string") return pyStrRepr(value);
  if (Array.isArray(value)) return "[" + value.map(pyRepr).join(", ") + "]";
  return "{" + Object.keys(value).map((k) => pyStrRepr(k) + ": " + pyRepr(value[k])).join(", ") + "}";
}

function stableHash(s: string): number {
  let h = 0;
  for (const c of s) h = (Math.imul(h, 31) + c.charCodeAt(0)) >>> 0;
  return h;
}

const SIMULATED_LATENCY_MS: Record<string, number> = { Bengaluru: 400, Tokyo: 600, Zurich: 800 };

async function executor_weather(city: string): Promise<JsonObject> {
  const latency = SIMULATED_LATENCY_MS[city] ?? 500;
  await sleep(latency);
  return { city, temp_c: stableHash(city) % 35 };
}

async function run_sequential(cities: string[]): Promise<[number, JsonObject[]]> {
  const start = performance.now();
  const results: JsonObject[] = [];
  for (const c of cities) results.push(await executor_weather(c));
  const dt_ms = performance.now() - start;
  return [dt_ms, results];
}

async function run_parallel(cities: string[]): Promise<[number, JsonObject[]]> {
  const start = performance.now();
  const results = await Promise.all(cities.map((c) => executor_weather(c)));
  const dt_ms = performance.now() - start;
  return [dt_ms, results];
}

class CallBuffer {
  constructor(
    public id: string,
    public name: string = "",
    public args_buf: string = "",
    public done: boolean = false,
  ) {}

  try_parse(): JsonObject | null {
    if (!this.done) return null;
    return JSON.parse(this.args_buf);
  }
}

type StreamEvent = { type: string; id?: string; name?: string; chunk?: string };

class StreamAccumulator {
  buffers: Map<string, CallBuffer> = new Map();

  on_event(event: StreamEvent): CallBuffer[] {
    const kind = event.type;
    const idx = event.id as string;
    const completed: CallBuffer[] = [];
    if (kind === "call_start") {
      this.buffers.set(idx, new CallBuffer(idx, event.name as string));
    } else if (kind === "args_delta") {
      const buf = this.buffers.get(idx) as CallBuffer;
      buf.args_buf += event.chunk as string;
    } else if (kind === "call_stop") {
      const buf = this.buffers.get(idx) as CallBuffer;
      buf.done = true;
      completed.push(buf);
    }
    return completed;
  }
}

function* fake_openai_stream(): Generator<StreamEvent> {
  yield { type: "call_start", id: "call_A", name: "get_weather" };
  yield { type: "call_start", id: "call_B", name: "get_weather" };
  yield { type: "call_start", id: "call_C", name: "get_weather" };
  yield { type: "args_delta", id: "call_A", chunk: '{"city"' };
  yield { type: "args_delta", id: "call_B", chunk: '{"city' };
  yield { type: "args_delta", id: "call_A", chunk: ':"Beng' };
  yield { type: "args_delta", id: "call_C", chunk: '{"city":"Zu' };
  yield { type: "args_delta", id: "call_A", chunk: 'aluru"}' };
  yield { type: "call_stop", id: "call_A" };
  yield { type: "args_delta", id: "call_B", chunk: '":"Tokyo"}' };
  yield { type: "call_stop", id: "call_B" };
  yield { type: "args_delta", id: "call_C", chunk: 'rich"}' };
  yield { type: "call_stop", id: "call_C" };
}

async function replay_and_execute(): Promise<Map<string, JsonObject>> {
  const acc = new StreamAccumulator();
  const results: Map<string, JsonObject> = new Map();
  const in_flight: Map<string, Promise<JsonObject>> = new Map();
  for (const event of fake_openai_stream()) {
    const completed = acc.on_event(event);
    for (const buf of completed) {
      const args = buf.try_parse() as JsonObject;
      console.log(`  call ${buf.id} args complete -> ${pyRepr(args)}`);
      in_flight.set(buf.id, executor_weather(args["city"] as string));
    }
  }
  for (const [cid, fut] of in_flight) results.set(cid, await fut);
  return results;
}

async function main(): Promise<void> {
  console.log("=".repeat(72));
  console.log("PHASE 13 LESSON 03 - PARALLEL AND STREAMING TOOL CALLS");
  console.log("=".repeat(72));

  const cities = ["Bengaluru", "Tokyo", "Zurich"];
  const latencies = Object.values(SIMULATED_LATENCY_MS);
  const sum_lat = latencies.reduce((a, b) => a + b, 0);
  const max_lat = Math.max(...latencies);

  console.log("\n--- demo 1: three-city weather (simulated) ---");
  console.log(`per-city simulated latency : ${pyRepr(SIMULATED_LATENCY_MS)}`);
  console.log(`theoretical sequential     : ${sum_lat} ms  (sum)`);
  console.log(`theoretical parallel       : ${max_lat} ms  (max)`);

  const [seq_ms] = await run_sequential(cities);
  const [par_ms] = await run_parallel(cities);
  console.log(`\nactual sequential : ${seq_ms.toFixed(0)} ms`);
  console.log(`actual parallel   : ${par_ms.toFixed(0)} ms`);
  const speedup = par_ms ? seq_ms / par_ms : 0;
  console.log(`speedup           : ${speedup.toFixed(2)}x`);

  console.log("\n--- demo 2: stream accumulator ---");
  console.log("replaying fake interleaved stream of three parallel calls ...");
  const results = await replay_and_execute();
  console.log("\nfinal results (keyed by tool_call_id):");
  for (const [cid, r] of results) console.log(`  ${cid} -> ${pyRepr(r)}`);
}

void main();
